using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Clients;[Authorize(Policy="SuperAdminOnly")]public sealed class UsersModel(OrcaFacilDbContext db):PageModel{public Guid ClientKey{get;private set;}public IReadOnlyList<Row>Users{get;private set;}=[];public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){if(!await db.BusinessAccounts.AnyAsync(x=>x.Id==id&&!x.IsDeleted,ct))return NotFound();ClientKey=id;Users=await(from m in db.AccountMembers.AsNoTracking()join u in db.Users.AsNoTracking()on m.UserId equals u.Id where m.AccountId==id&&!m.IsDeleted&&!u.IsDeleted orderby u.Name select new Row(u.Name,u.Email,u.DocumentNumber??"—",m.RoleCode,m.Status.ToString(),u.LastLoginAt.HasValue?u.LastLoginAt.Value.ToString("g"):"Nunca")).ToListAsync(ct);return Page();}public sealed record Row(string Name,string Email,string Document,string Profile,string Status,string LastLogin);}
